import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer, PieChart, Pie, Cell 
} from 'recharts';
import { 
  LayoutDashboard, Users, FileText, Settings, Plus, LogOut, Building2, Calendar as CalendarIcon, 
  Edit3, Save, CheckCircle, Menu, X, UserPlus, Share2, Lightbulb, Briefcase, Shield, UserCog, 
  XCircle, Check, Download, PanelLeftClose, PanelLeftOpen, User, Clock, AlertTriangle, TrendingUp, 
  MinusCircle, UploadCloud, FileSpreadsheet, ChevronLeft, ChevronRight, History, Trash2, Search, Filter 
} from 'lucide-react';

// Firebase Imports
import { initializeApp } from 'firebase/app';
import { getAuth, signInAnonymously, onAuthStateChanged, signInWithCustomToken } from 'firebase/auth';
import { 
  getFirestore, collection, addDoc, updateDoc, deleteDoc, doc, onSnapshot, query, getDocs, writeBatch 
} from 'firebase/firestore';

// --- Configuration & Initialization ---

const getFirebaseConfig = () => {
  const win = window as any;
  // ตรวจสอบตัวแปรระบบจากสภาพแวดล้อม Preview
  if (win.__firebase_config) {
    try {
      return JSON.parse(win.__firebase_config);
    } catch (e) {
      console.error("Firebase config parsing error", e);
    }
  }
  
  // --- สำหรับใช้งานใน VS Code: กรุณาแก้ไขค่าด้านล่างนี้ด้วยข้อมูลจาก Firebase Console ของคุณ ---
  return {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_PROJECT_ID.firebaseapp.com",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_PROJECT_ID.appspot.com",
    messagingSenderId: "YOUR_SENDER_ID",
    appId: "YOUR_APP_ID"
  };
};

const firebaseConfig = getFirebaseConfig();
const app = initializeApp(firebaseConfig);
const auth = getAuth(app);
const db = getFirestore(app);

// ดึงค่า appId และ token อย่างปลอดภัยจาก window object เพื่อป้องกัน TypeScript Error
const getGlobalVar = (key: string): any => {
  const win = window as any;
  return win[key] || null;
};

const appId = getGlobalVar('__app_id') || 'default-hr-app';
const initialToken = getGlobalVar('__initial_auth_token');

// --- Theme & Style Config ---
const THEME = {
  bg: 'bg-gray-50', 
  card: 'bg-white shadow-sm border border-gray-100', 
  primary: 'bg-red-700 hover:bg-red-800', 
  secondary: 'bg-gray-100 hover:bg-gray-200 text-gray-700',
  accent: 'text-red-700',
  textMain: 'text-gray-800',
  textMuted: 'text-gray-400',
  border: 'border-gray-200'
};

const COLORS = ['#b91c1c', '#f87171', '#fee2e2', '#9ca3af']; 
const MAX_ANNUAL_LEAVE = 30;
const CURRENT_YEAR = new Date().getFullYear();

// --- Constants ---
const RECOMMENDATIONS = [
  { title: 'การจัดการวันลา', desc: 'เจ้าหน้าที่คัดกรองข้อมูลเบื้องต้นได้ดี ช่วยลดขั้นตอนการอนุมัติส่วนกลางได้มาก' },
  { title: 'สถิติประจำเดือน', desc: 'พบแนวโน้มการลาป่วยเพิ่มขึ้นในช่วงปลายปี ควรเตรียมมาตรการดูแลสุขภาพพนักงาน' }
];

// --- Global Sub-Components ---

const Card: React.FC<{ children: React.ReactNode; className?: string }> = ({ children, className = '' }) => (
  <div className={`${THEME.card} rounded-xl p-6 transition-shadow hover:shadow-md ${className}`}>
    {children}
  </div>
);

const Button: React.FC<{ 
  children: React.ReactNode; 
  onClick?: () => void; 
  variant?: 'primary' | 'secondary' | 'outline' | 'success' | 'danger'; 
  className?: string; 
  icon?: any; 
  size?: 'sm' | 'md' 
}> = ({ children, onClick, variant = 'primary', className = '', icon: Icon, size='md' }) => {
  const sizeClass = size === 'sm' ? "px-2 py-1 text-xs" : "px-4 py-2";
  const baseStyle = `${sizeClass} rounded-lg font-medium transition-all duration-200 flex items-center justify-center gap-2 active:scale-95`;
  const variants = {
    primary: `${THEME.primary} text-white shadow-sm shadow-red-200`,
    secondary: `${THEME.secondary}`,
    outline: `border ${THEME.border} bg-white hover:bg-gray-50 text-gray-700`,
    success: `bg-green-100 hover:bg-green-200 text-green-700`,
    danger: `bg-red-50 hover:bg-red-100 text-red-700 border border-red-100`
  };
  return (
    <button onClick={onClick} className={`${baseStyle} ${variants[variant]} ${className}`}>
      {Icon && <Icon size={size === 'sm' ? 14 : 18} />}
      {children}
    </button>
  );
};

const Toast: React.FC<{ message: string; type: 'success' | 'error'; onClose: () => void }> = ({ message, type, onClose }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 3000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className={`fixed top-4 right-4 z-50 flex items-center gap-3 px-4 py-3 rounded-lg shadow-lg transform transition-all animate-fade-in-up ${
      type === 'success' ? 'bg-white border-l-4 border-green-500 text-gray-800' : 'bg-white border-l-4 border-red-500 text-gray-800'
    }`}>
      {type === 'success' ? <CheckCircle className="text-green-500" size={20} /> : <AlertTriangle className="text-red-500" size={20} />}
      <span className="font-medium text-sm">{message}</span>
      <button onClick={onClose} className="ml-4 text-gray-400 hover:text-gray-600"><X size={16} /></button>
    </div>
  );
};

const NavItem: React.FC<{ active: boolean; onClick: () => void; icon: any; label: string }> = ({ active, onClick, icon: Icon, label }) => (
  <button 
    onClick={onClick} 
    className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all group font-medium ${active ? 'bg-red-50 text-red-700' : 'text-gray-500 hover:bg-gray-50 hover:text-gray-900'}`}
  >
    <Icon size={20} className={`${active ? 'text-red-600' : 'text-gray-400 group-hover:text-gray-600'}`} />
    <span>{label}</span>
    {active && <div className="ml-auto w-1.5 h-1.5 rounded-full bg-red-600"></div>}
  </button>
);

const ActivityIcon = ({ size }: { size: number }) => (<svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M22 12h-4l-3 9L9 3l-3 9H2"/></svg>);
const SunIcon = ({ size }: { size: number }) => (<svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="5"/><path d="M12 1v2"/><path d="M12 21v2"/><path d="M4.22 4.22l1.42 1.42"/><path d="M18.36 18.36l1.42 1.42"/><path d="M1 12h2"/><path d="M21 12h2"/><path d="M4.22 19.78l1.42-1.42"/><path d="M18.36 5.64l1.42-1.42"/></svg>);
const ChartIcon = ({ size, className }: { size: number; className?: string }) => (<svg className={className} width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="20" x2="18" y2="10"></line><line x1="12" y1="20" x2="12" y2="4"></line><line x1="6" y1="20" x2="6" y2="14"></line></svg>);

// --- Main Application ---

export default function App() {
  const [user, setUser] = useState<any>(null);
  const [view, setView] = useState('dashboard'); 
  const [role, setRole] = useState('super_admin'); 
  
  // Data States
  const [partnerships, setPartnerships] = useState<any[]>([]);
  const [employees, setEmployees] = useState<any[]>([]);
  const [leaveRecords, setLeaveRecords] = useState<any[]>([]);

  // UI States
  const [selectedPartnershipId, setSelectedPartnershipId] = useState('all');
  const [dateFilter, setDateFilter] = useState('all'); 
  const [dashboardTab, setDashboardTab] = useState('overview'); 
  const [searchTerm, setSearchTerm] = useState(''); 
  const [employeeSearch, setEmployeeSearch] = useState('');
  const [newLeave, setNewLeave] = useState<any>({ empId: '', type: 'ลากิจ', days: 1, date: '', reason: '' });
  const [newEmp, setNewEmp] = useState<any>({ name: '', position: '', partnershipId: '' });
  const [editingName, setEditingName] = useState<any>({ id: null, name: '' });
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [desktopSidebarOpen, setDesktopSidebarOpen] = useState(true);
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null); 

  // --- 1. Authentication ---
  useEffect(() => {
    const initAuth = async () => {
      try {
        if (initialToken) {
          await signInWithCustomToken(auth, initialToken);
        } else {
          await signInAnonymously(auth);
        }
      } catch (e: any) {
        console.error("Auth initialization error", e);
        if (e.code === 'auth/api-key-not-valid') {
           setToast({ message: "กรุณาตรวจสอบ Firebase API Key ในไฟล์ App.tsx", type: 'error' });
        }
      }
    };
    initAuth();
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
    });
    return () => unsubscribe();
  }, []);

  // Seed Data Function
  const seedInitialData = useCallback(async () => {
    try {
      const batch = writeBatch(db);
      const p1Ref = doc(collection(db, 'artifacts', appId, 'public', 'data', 'partnerships'));
      batch.set(p1Ref, { name: 'หจก. HR' });
      const p2Ref = doc(collection(db, 'artifacts', appId, 'public', 'data', 'partnerships'));
      batch.set(p2Ref, { name: 'แก้วเกรียงไกร' });
      
      const eRef = collection(db, 'artifacts', appId, 'public', 'data', 'employees');
      const e1 = doc(eRef); batch.set(e1, { name: 'คุณสมศรี (HR)', position: 'HR Manager', partnershipId: p1Ref.id });
      const e2 = doc(eRef); batch.set(e2, { name: 'นายช่างแก้ว', position: 'หัวหน้าช่าง', partnershipId: p2Ref.id });
      
      await batch.commit();
    } catch (e) {
      console.error("Seed error:", e);
    }
  }, []);

  // --- 2. Data Syncing ---
  useEffect(() => {
    if (!user) return;

    const pRef = collection(db, 'artifacts', appId, 'public', 'data', 'partnerships');
    const unsubPartnerships = onSnapshot(pRef, (snapshot) => {
      const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      setPartnerships(data);
      if (data.length === 0) seedInitialData(); 
    }, (error) => console.error("Firestore error (partnerships):", error));

    const eRef = collection(db, 'artifacts', appId, 'public', 'data', 'employees');
    const unsubEmployees = onSnapshot(eRef, (snapshot) => {
      setEmployees(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    }, (error) => console.error("Firestore error (employees):", error));

    const lRef = collection(db, 'artifacts', appId, 'public', 'data', 'leave_records');
    const unsubLeaves = onSnapshot(lRef, (snapshot) => {
      setLeaveRecords(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    }, (error) => console.error("Firestore error (leaves):", error));

    return () => {
      unsubPartnerships();
      unsubEmployees();
      unsubLeaves();
    };
  }, [user, seedInitialData]);

  // --- Handlers ---
  const handleAddLeave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newLeave.empId || !newLeave.date) {
      setToast({ message: 'กรุณากรอกข้อมูลให้ครบถ้วน', type: 'error' });
      return;
    }
    try {
      await addDoc(collection(db, 'artifacts', appId, 'public', 'data', 'leave_records'), {
        ...newLeave,
        status: 'Approved',
        timestamp: new Date().toISOString()
      });
      setToast({ message: 'บันทึกข้อมูลเรียบร้อย', type: 'success' });
      setNewLeave({ empId: '', type: 'ลากิจ', days: 1, date: '', reason: '' });
    } catch (err) {
      setToast({ message: 'เกิดข้อผิดพลาดในการบันทึก', type: 'error' });
    }
  };

  const handleDeleteLeave = async (id: string) => {
    if (window.confirm('คุณต้องการลบรายการนี้ใช่หรือไม่?')) {
      try {
        await deleteDoc(doc(db, 'artifacts', appId, 'public', 'data', 'leave_records', id));
        setToast({ message: 'ลบรายการเรียบร้อย', type: 'success' });
      } catch (err) {
        setToast({ message: 'ไม่สามารถลบข้อมูลได้', type: 'error' });
      }
    }
  };

  const handleAddEmployee = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEmp.name || !newEmp.partnershipId) return;
    try {
      await addDoc(collection(db, 'artifacts', appId, 'public', 'data', 'employees'), newEmp);
      setNewEmp({ name: '', position: '', partnershipId: '' });
      setToast({ message: 'เพิ่มพนักงานเรียบร้อย', type: 'success' });
    } catch (err) {
      setToast({ message: 'เกิดข้อผิดพลาด', type: 'error' });
    }
  };

  const handleDeleteEmployee = async (id: string) => {
    if (window.confirm('ยืนยันการลบข้อมูลพนักงาน? ข้อมูลการลาจะหายไปด้วย')) {
      try {
        await deleteDoc(doc(db, 'artifacts', appId, 'public', 'data', 'employees', id));
        setToast({ message: 'ลบข้อมูลพนักงานเรียบร้อย', type: 'success' });
      } catch (e) {
        setToast({ message: 'ลบข้อมูลไม่สำเร็จ', type: 'error' });
      }
    }
  };

  const handleUpdatePartnershipName = async (id: string) => {
    try {
      await updateDoc(doc(db, 'artifacts', appId, 'public', 'data', 'partnerships', id), { name: editingName.name });
      setEditingName({ id: null, name: '' });
      setToast({ message: 'อัปเดตชื่อ หจก. เรียบร้อย', type: 'success' });
    } catch (e) {
      setToast({ message: 'อัปเดตไม่สำเร็จ', type: 'error' });
    }
  };

  const handleResetSystem = async () => {
    if (window.confirm('คำเตือน: คุณแน่ใจหรือไม่ที่จะล้างข้อมูลทั้งหมดในระบบ?')) {
      try {
        const collections = ['partnerships', 'employees', 'leave_records'];
        for (const colName of collections) {
          const q = collection(db, 'artifacts', appId, 'public', 'data', colName);
          const snap = await getDocs(q);
          const batch = writeBatch(db);
          snap.docs.forEach(d => batch.delete(d.ref));
          await batch.commit();
        }
        setToast({ message: 'รีเซ็ตระบบเรียบร้อย', type: 'success' });
      } catch (e: any) {
        setToast({ message: 'รีเซ็ตไม่สำเร็จ: ' + e.message, type: 'error' });
      }
    }
  };

  const handleExportCSV = () => {
    const headers = ['วันที่', 'พนักงาน', 'หจก.', 'ประเภทการลา', 'จำนวนวัน', 'สถานะ'];
    const rows = filteredRecords.map(r => {
      const emp = employees.find(e => e.id === r.empId);
      const part = partnerships.find(p => p.id === emp?.partnershipId);
      return [r.date, emp?.name || 'Unknown', part?.name || '-', r.type, r.days, r.status].join(',');
    });
    const csvContent = "data:text/csv;charset=utf-8," + "\uFEFF" + [headers.join(','), ...rows].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `leave_report_${new Date().toISOString().slice(0,10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setToast({ message: 'ดาวน์โหลดรายงานสำเร็จ', type: 'success' });
  };

  const switchToAdmin = () => { setRole('super_admin'); setView('dashboard'); setSelectedPartnershipId('all'); setSearchTerm(''); };
  const switchToStaffHR = () => { setRole('staff_hr'); setView('entry'); setSearchTerm(''); };
  const switchToStaffKK = () => { setRole('staff_kk'); setView('entry'); setSearchTerm(''); };

  // --- Computed ---
  const filteredRecords = useMemo(() => {
    let targetPid = selectedPartnershipId;
    const p_hr = partnerships.find(p => p.name.includes('HR'))?.id;
    const p_kk = partnerships.find(p => p.name.includes('แก้ว'))?.id;
    if (role === 'staff_hr') targetPid = p_hr || 'none';
    if (role === 'staff_kk') targetPid = p_kk || 'none';
    
    let records = leaveRecords;
    if (targetPid !== 'all' && targetPid !== '') {
      const pEmpIds = employees.filter(e => e.partnershipId === targetPid).map(e => e.id);
      records = records.filter(r => pEmpIds.includes(r.empId));
    }
    if (dateFilter !== 'all') {
      const now = new Date();
      records = records.filter(r => {
        const rDate = new Date(r.date);
        if (dateFilter === 'this_month') return rDate.getMonth() === now.getMonth() && rDate.getFullYear() === now.getFullYear();
        if (dateFilter === 'this_year') return rDate.getFullYear() === now.getFullYear();
        return true;
      });
    }
    if (searchTerm) {
      records = records.filter(r => {
        const emp = employees.find(e => e.id === r.empId);
        return emp?.name.toLowerCase().includes(searchTerm.toLowerCase());
      });
    }
    return records;
  }, [selectedPartnershipId, leaveRecords, employees, role, searchTerm, dateFilter, partnerships]);

  const stats = useMemo(() => {
    const totalLeaves = filteredRecords.reduce((acc, curr) => (curr.status === 'Approved' ? acc + (Number(curr.days) || 0) : acc), 0);
    const sickLeaves = filteredRecords.filter(r => r.type === 'ลาป่วย' && r.status === 'Approved').reduce((acc, curr) => acc + (Number(curr.days) || 0), 0);
    const vacationLeaves = filteredRecords.filter(r => r.type === 'พักร้อน' && r.status === 'Approved').reduce((acc, curr) => acc + (Number(curr.days) || 0), 0);
    return { totalLeaves, sickLeaves, vacationLeaves };
  }, [filteredRecords]);

  const chartData = useMemo(() => {
    const types = ['ลาป่วย', 'ลากิจ', 'พักร้อน', 'อื่นๆ'];
    return types.map(type => ({
      name: type,
      value: filteredRecords.filter(r => r.type === type && r.status === 'Approved').reduce((acc, curr) => acc + (Number(curr.days) || 0), 0)
    })).filter(d => d.value > 0);
  }, [filteredRecords]);

  const topLeavers = useMemo(() => {
    const leaveMap: Record<string, number> = {};
    filteredRecords.forEach(r => {
      if (r.status === 'Approved') {
        if (!leaveMap[r.empId]) leaveMap[r.empId] = 0;
        leaveMap[r.empId] += (Number(r.days) || 0);
      }
    });
    return Object.entries(leaveMap)
      .map(([id, days]) => ({ empId: id, days, employee: employees.find(e => e.id === id) }))
      .filter(item => item.employee)
      .sort((a, b) => Number(b.days) - Number(a.days));
  }, [filteredRecords, employees]);

  const filteredEmployeesSettings = useMemo(() => {
    return employees.filter(e => 
      e.name.toLowerCase().includes(employeeSearch.toLowerCase()) ||
      e.position.toLowerCase().includes(employeeSearch.toLowerCase())
    );
  }, [employees, employeeSearch]);

  const getEmployeeUsedLeaves = useCallback((empId: string) => {
    if (!empId) return 0;
    return leaveRecords.filter(r => r.empId === empId && r.status === 'Approved').reduce((acc, curr) => acc + (Number(curr.days) || 0), 0);
  }, [leaveRecords]);

  // --- Views ---

  const CalendarView = () => {
    const daysInMonth = 30;
    const startDayOffset = 3; 
    const days = [];
    for (let i = 0; i < startDayOffset; i++) days.push(null);
    for (let i = 1; i <= daysInMonth; i++) days.push(i);

    return (
      <Card>
        <div className="flex justify-between items-center mb-6">
          <div className="flex items-center gap-2">
            <CalendarIcon className="text-red-700" size={24} />
            <h3 className="text-lg font-bold text-gray-800">เดือนนี้ {CURRENT_YEAR}</h3>
          </div>
          <div className="flex gap-2">
            <button className="p-1 rounded hover:bg-gray-100 text-gray-400"><ChevronLeft /></button>
            <button className="p-1 rounded hover:bg-gray-100 text-gray-400"><ChevronRight /></button>
          </div>
        </div>
        <div className="grid grid-cols-7 gap-1">
          {['อา', 'จ', 'อ', 'พ', 'พฤ', 'ศ', 'ส'].map(d => (
            <div key={d} className="text-center text-xs font-semibold text-gray-400 py-2">{d}</div>
          ))}
          {days.map((day, idx) => {
            if (!day) return <div key={idx} className="bg-transparent h-24 md:h-32"></div>;
            const dayStr = `${CURRENT_YEAR}-${(new Date().getMonth()+1).toString().padStart(2, '0')}-${day.toString().padStart(2, '0')}`;
            const dayLeaves = filteredRecords.filter(r => r.date === dayStr);
            return (
              <div key={idx} className="border border-gray-100 h-24 md:h-32 p-1 relative hover:bg-gray-50 transition-colors">
                <span className={`text-sm font-medium p-1 ${dayLeaves.length > 0 ? 'text-red-600' : 'text-gray-700'}`}>{day}</span>
                <div className="mt-1 space-y-1 overflow-y-auto max-h-[70px]">
                  {dayLeaves.map(r => {
                    const emp = employees.find(e => e.id === r.empId);
                    return (
                      <div key={r.id} className={`text-[10px] p-1 rounded truncate ${
                        r.type === 'ลาป่วย' ? 'bg-gray-200 text-gray-700' : 
                        r.type === 'พักร้อน' ? 'bg-orange-100 text-orange-700' : 'bg-red-100 text-red-700'
                      }`}>
                        {emp?.name.split(' ')[0]} ({r.type})
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      </Card>
    );
  };

  const DashboardView = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4">
        <div>
          <h2 className={`text-2xl font-bold ${THEME.textMain}`}>ภาพรวมการลา</h2>
          <div className="flex items-center gap-2 mt-1">
             <span className="px-2 py-0.5 rounded text-xs font-semibold bg-gray-800 text-white">SCG Heim Admin</span>
             <p className="text-gray-400 text-sm">| ระบบออนไลน์</p>
          </div>
        </div>
        <div className="flex flex-wrap gap-2 w-full lg:w-auto">
           <div className="flex items-center gap-2 bg-white p-2 rounded-lg border border-gray-200 shadow-sm">
              <Filter size={16} className="text-gray-400" />
              <select className="bg-transparent outline-none text-gray-700 font-medium cursor-pointer text-sm" value={dateFilter} onChange={(e) => setDateFilter(e.target.value)}>
                <option value="all">ทั้งหมด</option>
                <option value="this_year">ปีนี้ ({CURRENT_YEAR})</option>
                <option value="this_month">เดือนนี้</option>
              </select>
           </div>
           <div className="bg-gray-100 p-1 rounded-lg flex mr-2 overflow-x-auto">
             <button onClick={() => setDashboardTab('overview')} className={`px-3 py-1.5 text-sm font-medium rounded-md whitespace-nowrap transition-all ${dashboardTab === 'overview' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>ภาพรวม</button>
             <button onClick={() => setDashboardTab('stats')} className={`px-3 py-1.5 text-sm font-medium rounded-md whitespace-nowrap transition-all flex items-center gap-1 ${dashboardTab === 'stats' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}><TrendingUp size={14} /> สถิติ</button>
             <button onClick={() => setDashboardTab('calendar')} className={`px-3 py-1.5 text-sm font-medium rounded-md whitespace-nowrap transition-all flex items-center gap-1 ${dashboardTab === 'calendar' ? 'bg-white text-gray-800 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}><CalendarIcon size={14} /> ปฏิทิน</button>
           </div>
           <Button variant="outline" icon={Download} onClick={handleExportCSV}>Export CSV</Button>
           {role === 'super_admin' && (
             <div className="flex items-center gap-2 bg-white p-2 rounded-lg border border-gray-200 shadow-sm min-w-[200px]">
              <Building2 size={18} className="text-gray-400" />
              <select className="bg-transparent outline-none text-gray-700 font-medium cursor-pointer w-full" value={selectedPartnershipId} onChange={(e) => setSelectedPartnershipId(e.target.value)}>
                <option value="all">ดูข้อมูลทุก หจก.</option>
                {partnerships.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
              </select>
            </div>
           )}
        </div>
      </div>

      {dashboardTab === 'overview' && (
        <>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <Card>
              <div className="flex justify-between items-start">
                <div><p className="text-gray-400 text-xs font-medium uppercase tracking-wide">วันลาอนุมัติแล้ว</p><h3 className="text-3xl font-bold text-gray-800 mt-2">{stats.totalLeaves} <span className="text-sm text-gray-400 font-normal">วัน</span></h3></div>
                <div className="p-3 bg-red-50 rounded-xl text-red-600"><FileText size={22} /></div>
              </div>
            </Card>
            <Card>
              <div className="flex justify-between items-start">
                <div><p className="text-gray-400 text-xs font-medium uppercase tracking-wide">ลาป่วยสะสม</p><h3 className="text-3xl font-bold text-gray-800 mt-2">{stats.sickLeaves} <span className="text-sm text-gray-400 font-normal">วัน</span></h3></div>
                <div className="p-3 bg-gray-100 rounded-xl text-gray-600"><ActivityIcon size={22} /></div>
              </div>
            </Card>
            <Card>
              <div className="flex justify-between items-start">
                <div><p className="text-gray-400 text-xs font-medium uppercase tracking-wide">พักร้อนสะสม</p><h3 className="text-3xl font-bold text-gray-800 mt-2">{stats.vacationLeaves} <span className="text-sm text-gray-400 font-normal">วัน</span></h3></div>
                <div className="p-3 bg-orange-50 rounded-xl text-orange-500"><SunIcon size={22} /></div>
              </div>
            </Card>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mt-6">
            <Card>
              <h3 className="text-lg font-semibold text-gray-800 mb-6 flex items-center gap-2"><ChartIcon className="text-gray-400" size={20} /> สัดส่วนประเภทการลา</h3>
              <div className="h-72 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={chartData} cx="50%" cy="50%" innerRadius={80} outerRadius={100} fill="#8884d8" paddingAngle={5} dataKey="value">
                      {chartData.map((_entry, index) => (<Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} stroke="white" strokeWidth={2} />))}
                    </Pie>
                    <RechartsTooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)' }} />
                    <Legend verticalAlign="bottom" height={36} iconType="circle" />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </Card>

            <Card>
              <h3 className="text-lg font-semibold text-gray-800 mb-6 flex items-center gap-2"><Lightbulb className="text-yellow-500" size={20} /> คำแนะนำ</h3>
              <div className="space-y-4">
                {RECOMMENDATIONS.map((rec, idx) => (
                  <div key={idx} className="p-4 rounded-xl bg-gray-50 border border-gray-100">
                    <h4 className="font-bold text-gray-800 text-sm">{rec.title}</h4>
                    <p className="text-xs text-gray-500 mt-1">{rec.desc}</p>
                  </div>
                ))}
              </div>
            </Card>
          </div>

          <Card className="overflow-hidden mt-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
              <h3 className="text-lg font-semibold text-gray-800">รายการล่าสุด</h3>
              <div className="relative w-full md:w-64">
                <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
                <input type="text" placeholder="ค้นหาชื่อ..." className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-lg text-sm outline-none focus:border-red-300 transition-colors" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
              </div>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="text-gray-400 text-xs uppercase border-b border-gray-100">
                    <th className="py-4 pl-4 font-medium">วันที่</th>
                    <th className="py-4 font-medium">พนักงาน</th>
                    <th className="py-4 font-medium">ประเภท</th>
                    <th className="py-4 font-medium">วัน</th>
                    <th className="py-4 text-right pr-4">จัดการ</th>
                  </tr>
                </thead>
                <tbody className="text-sm text-gray-600">
                  {filteredRecords.sort((a,b) => (b.date > a.date ? 1 : -1)).slice(0, 8).map(record => {
                    const emp = employees.find(e => e.id === record.empId);
                    return (
                      <tr key={record.id} className="border-b border-gray-50 hover:bg-gray-50 transition-colors last:border-0">
                        <td className="py-4 pl-4 text-gray-400">{record.date}</td>
                        <td className="py-4 font-medium text-gray-800">{emp?.name || 'Unknown'}</td>
                        <td className="py-4"><span className="px-2 py-1 bg-gray-100 rounded text-xs text-gray-600">{record.type}</span></td>
                        <td className="py-4">{record.days}</td>
                        <td className="py-4 text-right pr-4">
                           <button onClick={() => handleDeleteLeave(record.id)} className="text-gray-300 hover:text-red-500 transition-colors"><Trash2 size={16} /></button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </Card>
        </>
      )}

      {dashboardTab === 'stats' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <Card>
            <div className="flex items-center gap-2 mb-6"><div className="p-2 bg-red-50 text-red-700 rounded-lg"><MinusCircle size={20} /></div><h3 className="text-lg font-semibold text-gray-800">10 อันดับ พนักงานลาเยอะสุด</h3></div>
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead><tr className="text-gray-400 text-xs uppercase border-b border-gray-100"><th className="pb-3 pl-2">อันดับ</th><th className="pb-3">พนักงาน</th><th className="pb-3 text-right pr-2">รวมวันลา</th></tr></thead>
                <tbody className="text-sm">
                   {topLeavers.slice(0, 10).map((item, index) => (
                     <tr key={item.empId} className="border-b border-gray-50 last:border-0 hover:bg-gray-50">
                        <td className="py-3 pl-2"><span className={`flex items-center justify-center w-6 h-6 rounded-full text-xs font-bold text-white ${index === 0 ? 'bg-yellow-400' : index === 1 ? 'bg-gray-400' : 'bg-orange-400'}`}>{index + 1}</span></td>
                        <td className="py-3 font-medium text-gray-700">{item.employee.name}</td>
                        <td className="py-3 text-right pr-2 font-bold text-red-600">{item.days} วัน</td>
                     </tr>
                   ))}
                   {topLeavers.length === 0 && <tr><td colSpan={3} className="py-8 text-center text-gray-400">ไม่มีข้อมูล</td></tr>}
                </tbody>
              </table>
            </div>
          </Card>
        </div>
      )}

      {dashboardTab === 'calendar' && <CalendarView />}
    </div>
  );

  const EntryView = () => {
    const p_hr = partnerships.find(p => p.name.includes('HR'))?.id;
    const p_kk = partnerships.find(p => p.name.includes('แก้ว'))?.id;
    let activePid = role === 'staff_hr' ? p_hr : (role === 'staff_kk' ? p_kk : p_hr);
    const availableEmployees = employees.filter(e => e.partnershipId === activePid);
    const historyRecords = leaveRecords.filter(r => {
       const emp = employees.find(e => e.id === r.empId);
       return emp && emp.partnershipId === activePid;
    }).sort((a,b) => (b.date > a.date ? 1 : -1)).slice(0, 10);

    return (
      <div className="max-w-2xl mx-auto animate-fade-in">
        <div className="text-center mb-10">
          <h2 className="text-3xl font-bold text-gray-800 tracking-tight">บันทึกข้อมูลการลา</h2>
          <p className="text-gray-500 mt-2 font-light text-lg">สำหรับเจ้าหน้าที่ : <span className="text-red-700 font-semibold">{partnerships.find(p => p.id === activePid)?.name || ''}</span></p>
        </div>
        <Card className="border-0 shadow-lg shadow-gray-200/50 mb-8">
          <form onSubmit={handleAddLeave} className="space-y-6">
             <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">พนักงาน</label>
              <select required className="w-full p-3 bg-gray-50 border border-gray-200 rounded-lg focus:ring-2 focus:ring-red-100 focus:border-red-300 outline-none transition-all" value={newLeave.empId} onChange={e => setNewLeave({...newLeave, empId: e.target.value})}>
                <option value="">-- เลือกรายชื่อ --</option>
                {availableEmployees.map(e => (<option key={e.id} value={e.id}>{e.name}</option>))}
              </select>
            </div>
            {newLeave.empId && (
              <div className="bg-gray-50 p-5 rounded-xl border border-dashed border-gray-300">
                 <div className="flex justify-between items-end mb-3"><span className="text-sm font-bold text-gray-700">วันลาใช้ไปแล้ว</span><span className="text-xs text-gray-500 font-medium">{getEmployeeUsedLeaves(newLeave.empId)} / {MAX_ANNUAL_LEAVE} วัน</span></div>
                 <div className="w-full bg-gray-200 h-2 rounded-full overflow-hidden"><div className="h-full rounded-full bg-green-500" style={{ width: `${Math.min((getEmployeeUsedLeaves(newLeave.empId)/MAX_ANNUAL_LEAVE)*100, 100)}%` }}></div></div>
              </div>
            )}
            <div className="grid grid-cols-2 gap-6">
              <div><label className="block text-sm font-medium text-gray-700 mb-2">ประเภท</label><select className="w-full p-3 bg-gray-50 border border-gray-200 rounded-lg outline-none" value={newLeave.type} onChange={e => setNewLeave({...newLeave, type: e.target.value})}><option>ลากิจ</option><option>ลาป่วย</option><option>พักร้อน</option><option>ลาคลอด</option><option>อื่นๆ</option></select></div>
              <div><label className="block text-sm font-medium text-gray-700 mb-2">จำนวนวัน</label><input type="number" step="0.5" className="w-full p-3 bg-gray-50 border border-gray-200 rounded-lg outline-none" value={newLeave.days} onChange={e => setNewLeave({...newLeave, days: parseFloat(e.target.value)})} /></div>
            </div>
            <div><label className="block text-sm font-medium text-gray-700 mb-2">วันที่ลา</label><input type="date" className="w-full p-3 bg-gray-50 border border-gray-200 rounded-lg outline-none" value={newLeave.date} onChange={e => setNewLeave({...newLeave, date: e.target.value})} /></div>
            <div><label className="block text-sm font-medium text-gray-700 mb-2">รายละเอียด</label><textarea rows={3} className="w-full p-3 bg-gray-50 border border-gray-200 rounded-lg outline-none" value={newLeave.reason} onChange={e => setNewLeave({...newLeave, reason: e.target.value})} /></div>
            <div className="pt-4"><Button variant="primary" className="w-full py-3 shadow-lg shadow-red-200" icon={Save}>บันทึกข้อมูล</Button></div>
          </form>
        </Card>
        <Card>
           <div className="flex items-center gap-2 mb-4"><History size={20} className="text-gray-400" /><h3 className="text-lg font-semibold text-gray-800">ประวัติล่าสุด</h3></div>
           <div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead><tr className="border-b border-gray-100 text-gray-400 font-medium"><th className="pb-2">วันที่</th><th>พนักงาน</th><th>ประเภท</th><th className="text-right">จัดการ</th></tr></thead><tbody>
             {historyRecords.map(r => (<tr key={r.id} className="border-b border-gray-50 last:border-0 hover:bg-gray-50"><td className="py-3 text-gray-600">{r.date}</td><td className="py-3 font-medium">{employees.find(e => e.id === r.empId)?.name}</td><td className="py-3 text-gray-500">{r.type}</td><td className="py-3 text-right"><button onClick={() => handleDeleteLeave(r.id)} className="text-gray-300 hover:text-red-500"><Trash2 size={14} /></button></td></tr>))}
           </tbody></table></div>
        </Card>
      </div>
    );
  }

  const SettingsView = () => (
    <div className="space-y-6 animate-fade-in">
      <h2 className="text-2xl font-bold text-gray-800">ตั้งค่าระบบ</h2>
      <Card>
        <h3 className="text-lg font-semibold text-gray-800 mb-1 flex items-center gap-2"><Building2 size={20} className="text-red-700" /> รายชื่อ หจก.</h3>
        <div className="space-y-3 mt-4">{partnerships.map(p => (
            <div key={p.id} className="flex items-center justify-between p-4 bg-gray-50 border border-gray-100 rounded-xl">
              {editingName.id === p.id ? (<div className="flex gap-2 w-full"><input className="flex-1 p-2 border border-gray-300 rounded outline-none" value={editingName.name} onChange={e => setEditingName({...editingName, name: e.target.value})} autoFocus /><Button onClick={() => handleUpdatePartnershipName(p.id)} variant="primary" className="text-xs">บันทึก</Button><Button onClick={() => setEditingName({id: null, name: ''})} variant="outline" className="text-xs">ยกเลิก</Button></div>) : (<><span className="font-medium text-gray-700">{p.name}</span><button onClick={() => setEditingName({ id: p.id, name: p.name })} className="text-gray-400 hover:text-red-600 transition-colors"><Edit3 size={18} /></button></>)}
            </div>
        ))}</div>
      </Card>
      <Card>
        <h3 className="text-lg font-semibold text-gray-800 mb-6 flex items-center gap-2"><UserPlus size={20} className="text-red-700" /> เพิ่มพนักงาน</h3>
        <form onSubmit={handleAddEmployee} className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end mb-8">
          <div><label className="text-xs text-gray-500 font-medium ml-1">ชื่อ-นามสกุล</label><input required className="w-full p-2.5 bg-gray-50 border border-gray-200 rounded-lg mt-1" value={newEmp.name} onChange={e => setNewEmp({...newEmp, name: e.target.value})} /></div>
          <div><label className="text-xs text-gray-500 font-medium ml-1">ตำแหน่ง</label><input className="w-full p-2.5 bg-gray-50 border border-gray-200 rounded-lg mt-1 focus:border-red-300 outline-none" value={newEmp.position} onChange={e => setNewEmp({...newEmp, position: e.target.value})} /></div>
          <div><label className="text-xs text-gray-500 font-medium ml-1">สังกัด</label><select required className="w-full p-2.5 bg-gray-50 border border-gray-200 rounded-lg mt-1 focus:border-red-300 outline-none" value={newEmp.partnershipId} onChange={e => setNewEmp({...newEmp, partnershipId: e.target.value})}><option value="">เลือกสังกัด</option>{partnerships.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></div>
          <div className="md:col-span-1"><Button variant="secondary" className="w-full h-[44px]" icon={Plus}>เพิ่ม</Button></div>
        </form>
        <div className="mt-8 pt-6 border-t border-gray-100">
           <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4"><h3 className="text-lg font-semibold text-gray-800 flex items-center gap-2"><Users size={20} className="text-red-700" /> ฐานข้อมูลพนักงาน</h3><div className="relative w-full md:w-64"><Search className="absolute left-3 top-2.5 text-gray-400" size={16} /><input type="text" placeholder="ค้นหา..." className="w-full pl-9 pr-4 py-2 border border-gray-300 rounded-lg text-sm outline-none focus:border-red-300 transition-colors" value={employeeSearch} onChange={(e) => setEmployeeSearch(e.target.value)} /></div></div>
           <div className="overflow-x-auto border border-gray-200 rounded-xl"><table className="w-full text-left text-sm"><thead className="bg-gray-50"><tr className="text-gray-500 font-medium border-b border-gray-200"><th className="px-4 py-3">ชื่อ-นามสกุล</th><th className="px-4 py-3">ตำแหน่ง</th><th className="px-4 py-3">สังกัด</th><th className="px-4 py-3 text-right">จัดการ</th></tr></thead><tbody className="divide-y divide-gray-100">
                 {filteredEmployeesSettings.length > 0 ? filteredEmployeesSettings.map(emp => (
                   <tr key={emp.id} className="hover:bg-gray-50">
                     <td className="px-4 py-3 font-medium text-gray-800">{emp.name}</td>
                     <td className="px-4 py-3 text-gray-600">{emp.position}</td>
                     <td className="px-4 py-3 text-gray-600">{partnerships.find(p => p.id === emp.partnershipId)?.name}</td>
                     <td className="px-4 py-3 text-right">
                       <button onClick={() => handleDeleteEmployee(emp.id)} className="text-gray-400 hover:text-red-600 transition-colors p-1"><Trash2 size={16} /></button>
                     </td>
                   </tr>
                 )) : <tr><td colSpan={4} className="px-4 py-8 text-center text-gray-400">ไม่พบข้อมูลพนักงาน</td></tr>}
               </tbody>
             </table>
           </div>
        </div>
        <div className="mt-8 pt-6 border-t border-gray-100 flex justify-end">
           <button onClick={handleResetSystem} className="text-red-400 text-xs flex items-center gap-1 hover:text-red-600 transition-colors"><Trash2 size={12} /> รีเซ็ตข้อมูลระบบ (ล้างค่าทั้งหมด)</button>
        </div>
      </Card>
    </div>
  );

  return (
    <div className={`min-h-screen ${THEME.bg} font-sans text-gray-800 flex flex-col md:flex-row h-screen overflow-hidden`}>
      <aside className={`fixed md:relative top-0 left-0 h-full bg-white border-r border-gray-200 flex flex-col shadow-xl z-40 transition-all duration-300 w-64 ${mobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} md:translate-x-0 ${desktopSidebarOpen ? 'md:w-64' : 'md:w-0 md:opacity-0 md:overflow-hidden'}`}>
        <div className="w-64">
          <div className="p-6 border-b border-gray-100 flex items-center gap-2"><div className="w-8 h-8 bg-red-700 rounded-lg flex items-center justify-center text-white font-bold">S</div><div><h1 className="text-lg font-bold text-gray-800 tracking-tight">SCG HEIM<span className="text-red-600">.</span></h1><p className="text-[10px] text-gray-400 uppercase tracking-widest">HR System</p></div></div>
          <nav className="flex-1 p-4 space-y-1 mt-4">
            <NavItem active={view === 'dashboard'} onClick={switchToAdmin} icon={LayoutDashboard} label="ภาพรวม" />
            <NavItem active={view === 'entry'} onClick={switchToStaffHR} icon={FileText} label="บันทึกวันลา" />
            {role === 'super_admin' && (<NavItem active={view === 'settings'} onClick={() => {setView('settings'); setMobileMenuOpen(false)}} icon={Settings} label="ตั้งค่าข้อมูล" />)}
          </nav>
        </div>
      </aside>
      <div className="flex-1 flex flex-col h-full bg-gray-50 relative">
        {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
        <header className="bg-white border-b border-gray-200 h-16 flex items-center justify-between px-4 md:px-8 z-30 flex-shrink-0">
           <div className="flex items-center gap-4"><button onClick={() => setMobileMenuOpen(!mobileMenuOpen)} className="md:hidden text-gray-500"><Menu /></button><button onClick={() => setDesktopSidebarOpen(!desktopSidebarOpen)} className="hidden md:block text-gray-400 hover:text-gray-800 p-1 rounded hover:bg-gray-100">{desktopSidebarOpen ? <PanelLeftClose size={20} /> : <PanelLeftOpen size={20} />}</button><h2 className="text-lg font-semibold text-gray-800 hidden md:block">HR System</h2></div>
           <div className="flex items-center gap-2">
             <div className="flex bg-gray-100 p-1 rounded-lg">
                <button onClick={switchToAdmin} className={`px-3 py-1 rounded text-xs transition-all ${role === 'super_admin' ? 'bg-white text-red-700 shadow-sm' : 'text-gray-500'}`}>Admin</button>
                <button onClick={switchToStaffHR} className={`px-3 py-1 rounded text-xs transition-all ${role === 'staff_hr' ? 'bg-white text-red-700 shadow-sm' : 'text-gray-500'}`}>เจ้าหน้าที่: HR</button>
                <button onClick={switchToStaffKK} className={`px-3 py-1 rounded text-xs transition-all ${role === 'staff_kk' ? 'bg-white text-red-700 shadow-sm' : 'text-gray-500'}`}>เจ้าหน้าที่: แก้วเกรียงไกร</button>
             </div>
           </div>
        </header>
        <main className="flex-1 p-4 md:p-8 overflow-y-auto">
          {mobileMenuOpen && <div className="fixed inset-0 bg-black/20 z-20 md:hidden backdrop-blur-sm" onClick={() => setMobileMenuOpen(false)}></div>}
          {view === 'dashboard' && <DashboardView />}
          {view === 'entry' && <EntryView />}
          {view === 'settings' && <SettingsView />}
        </main>
      </div>
    </div>
  );
}